// Baustein 1: Mail bereinigen
// Erkennt manuell weitergeleitete Mails (Fwd/WG), zieht Originaldatum/-absender/-betreff heraus,
// entfernt Patreon-Footer und Tracking und liefert einen sauberen Beitragstext.

const FORWARD_MARKER = /-{3,}\s*(Forwarded message|Weitergeleitete Nachricht|Original Message|Ursprüngliche Nachricht)\s*-{3,}/i;
const FOOTER_MARKERS = [
  /^\s*unsubscribe\b/im,
  /^\s*abmelden\b/im,
  /you('|’)re receiving this (email|message)/i,
  /manage (your )?email (settings|preferences)/i,
  /patreon,? inc\.?/i,
  /download the patreon app/i,
  /get the patreon app/i,
];

function htmlToText(html) {
  return String(html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|h[1-6]|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;|&rsquo;/g, '’')
    .replace(/&quot;/g, '"');
}

function headerValue(block, names) {
  for (const name of names) {
    const m = block.match(new RegExp('^\\s*\\*?' + name + '\\*?:\\s*(.+)$', 'im'));
    if (m) return m[1].trim();
  }
  return '';
}

function stripTracking(text) {
  // Tracking-Parameter aus URLs entfernen, reine Tracking-/Bild-Platzhalter löschen
  return text
    .replace(/(https?:\/\/[^\s<>()\]]+)\?[^\s<>()\]]*/g, '$1')
    .replace(/\[image:[^\]]*\]/gi, '')
    .replace(/^\s*<https?:\/\/[^>]+>\s*$/gim, '');
}

function cutFooter(text) {
  let cut = text.length;
  for (const re of FOOTER_MARKERS) {
    const m = re.exec(text);
    if (m && m.index < cut && m.index > 40) cut = m.index;
  }
  return text.slice(0, cut);
}

function tidy(text) {
  return text
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const rawText = (m.text && String(m.text).trim()) ? String(m.text) : htmlToText(m.html);
  const subjectRaw = String(m.subject || '');

  let body = rawText;
  let isForwarded = false;
  let origFrom = (m.from && (m.from.text || m.from.value?.[0]?.address)) || '';
  let origDate = m.date || '';
  let origSubject = subjectRaw;

  const fwd = FORWARD_MARKER.exec(rawText);
  if (fwd) {
    isForwarded = true;
    const after = rawText.slice(fwd.index + fwd[0].length);
    // Kopfblock = bis zur ersten Leerzeile nach den Header-Zeilen
    const split = after.match(/^([\s\S]*?(?:\n\s*\n))([\s\S]*)$/);
    const headerBlock = split ? split[1] : '';
    body = split ? split[2] : after;
    origFrom = headerValue(headerBlock, ['From', 'Von']) || origFrom;
    origDate = headerValue(headerBlock, ['Date', 'Datum', 'Gesendet', 'Sent']) || origDate;
    origSubject = headerValue(headerBlock, ['Subject', 'Betreff']) || origSubject;
  }

  const subjectClean = origSubject.replace(/^\s*((fwd?|fw|wg|aw|re)\s*:\s*)+/i, '').trim();
  body = tidy(cutFooter(stripTracking(body)));

  const tickerMatch = subjectClean.match(/\$([A-Z][A-Z0-9.]{0,6})\b/) || body.match(/\$([A-Z][A-Z0-9.]{0,6})\b/);
  const postUrlMatch = (rawText + '\n' + String(m.html || '')).match(/https?:\/\/(?:www\.)?patreon\.com\/(?:[\w-]+\/)?posts\/[\w-]+/i);

  out.push({
    json: {
      gmail_message_id: m.id,
      gmail_thread_id: m.threadId,
      email_date: m.date || '',
      is_forwarded: isForwarded,
      original_from: origFrom,
      original_date_raw: origDate,
      subject: subjectClean,
      ticker_hint: tickerMatch ? tickerMatch[1] : '',
      post_url: postUrlMatch ? postUrlMatch[0] : '',
      body_clean: body,
      body_words: body ? body.split(/\s+/).length : 0,
      body_chars: body.length,
      check_body_ok: body.length >= 80,
    },
  });
}
return out;
